+	} else {
+		mode_map = &cfg->button_mappings[cfg->gamepad_mode];
+		ret = 0;
+		for (i = 0; i < 9; i++) {
+			mode_map->button_pairs[i].pair_index = i + 1;
+			ret = ally_set_button_mapping(hdev, ally,
